WITH lines AS (SELECT id, created_at, coupon_codes, elem.product_id, elem.qty, elem.price, elem.promo FROM carts LATERAL VIEW EXPLODE(items) e AS elem), lines_carts AS (SELECT id, product_id, qty, value FROM lines LATERAL VIEW EXPLODE(coupon_codes) li AS value), cleaned AS (SELECT *, ROUND(qty * 1.1, 2) qty_adjusted, COALESCE(value, 'OTHER') resolved_value FROM lines_carts WHERE value IS NOT NULL), filtered AS (SELECT *, CASE WHEN value IN ('VIP', 'BUNDLE') THEN 'Priority' ELSE 'Other' END value_group, CASE WHEN product_id >= 8 THEN 'High' WHEN product_id >= 4 THEN 'Medium' ELSE 'Low' END product_id_tier FROM cleaned WHERE value IS NOT NULL AND value IS NOT DISTINCT FROM 'VIP'), matched_keys AS (SELECT id FROM filtered EXCEPT SELECT id FROM carts WHERE customer_id = 21), kept_rows AS (SELECT s.* FROM filtered s INNER JOIN matched_keys k ON s.id = k.id), base AS (SELECT *, INITCAP(TRIM(value)) value_title, CAST(qty_adjusted AS INT) qty_adjusted_int, COALESCE(value, 'DIRECT') resolved_value_2 FROM kept_rows WHERE value IS NOT NULL AND value IS NOT NULL), valid AS (SELECT *, LEAST(qty, qty_adjusted_int) least_qty_qty_adjusted_int FROM base WHERE product_id IS NOT NULL) SELECT value, PERCENTILE_APPROX(product_id, 0.5) AS product_id_p50, COUNT(*) AS event_count, COUNT(*) AS cnt FROM valid GROUP BY value HAVING cnt >= 1 ORDER BY product_id_p50
